-- Japan: ES/DE/FR milestone translations for the 6 milestones in
-- migration 364. Hand-translated, not machine copy-paste.

-- jp-peppol-authority-2021
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-peppol-authority-2021', 'es', 'La Agencia Digital de Japón se pone en marcha y se convierte en la Autoridad Peppol de Japón', 'El 1 de septiembre de 2021, Japón creó su Agencia Digital, encargada de impulsar la transformación digital del país. La Agencia Digital ha actuado como la Autoridad Peppol oficial de Japón desde su fundación, liderando la iniciativa Japan Peppol eInvoice que más tarde desarrollaría JP PINT, la especificación de facturación electrónica propia de Japón conforme con Peppol PINT BIS Billing. Se trata de un hito institucional, no de un mandato -- sienta las bases de un estándar de facturación electrónica voluntario, no de un requisito legal para usarlo.', '["No se requiere ninguna acción -- esto es contexto de fondo para el estándar voluntario JP PINT/Peppol cubierto en hitos posteriores", "Si está evaluando estándares de facturación electrónica para comerciar con socios japoneses, tenga en cuenta que la Agencia Digital -- no la Agencia Nacional Tributaria -- es la autoridad detrás de la implementación de Peppol en Japón"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-peppol-authority-2021', 'de', 'Japans Digital Agency startet und wird Japans Peppol-Autorität', 'Am 1. September 2021 gründete Japan seine Digital Agency, die mit dem Vorantreiben der digitalen Transformation des Landes betraut ist. Die Digital Agency fungiert seit ihrer Gründung als Japans offizielle Peppol-Autorität und leitet die Initiative Japan Peppol eInvoice, aus der später JP PINT hervorging -- Japans eigene, Peppol-PINT-BIS-Billing-konforme E-Rechnungsspezifikation. Dies ist ein institutioneller Meilenstein, keine Pflicht -- er legt die Grundlage für einen freiwilligen elektronischen E-Rechnungsstandard, nicht für eine gesetzliche Nutzungspflicht.', '["Für diesen Meilenstein ist keine Handlung erforderlich -- er dient als Hintergrundinformation zum freiwilligen JP-PINT/Peppol-Standard, der in späteren Meilensteinen behandelt wird", "Wenn Sie E-Rechnungsstandards für den Handel mit japanischen Partnern prüfen, beachten Sie, dass die Digital Agency -- nicht die Nationale Steuerbehörde -- für Japans Peppol-Umsetzung zuständig ist"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-peppol-authority-2021', 'fr', 'L''Agence numérique du Japon est lancée et devient l''Autorité Peppol du Japon', 'Le 1er septembre 2021, le Japon a créé son Agence numérique, chargée de piloter la transformation numérique du pays. L''Agence numérique agit en tant qu''Autorité Peppol officielle du Japon depuis sa création, pilotant l''initiative Japan Peppol eInvoice qui allait donner naissance à JP PINT, la spécification de facturation électronique propre au Japon, conforme à Peppol PINT BIS Billing. Il s''agit d''un jalon institutionnel, non d''une obligation -- il pose les bases d''une norme de facturation électronique volontaire, et non d''une obligation légale de l''utiliser.', '["Aucune action n''est requise -- ceci constitue le contexte de fond pour la norme volontaire JP PINT/Peppol traitée dans les jalons suivants", "Si vous évaluez des normes de facturation électronique pour commercer avec des partenaires japonais, notez que l''Agence numérique -- et non l''administration fiscale nationale -- est l''autorité responsable de la mise en œuvre de Peppol au Japon"]');

-- jp-registration-opens-2021
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-registration-opens-2021', 'es', 'Se abre el registro del Sistema de Facturas Cualificadas ante la Agencia Nacional Tributaria', 'A partir del 1 de octubre de 2021, las empresas pudieron comenzar a solicitar ante la Agencia Nacional Tributaria de Japón (NTA) su registro como "emisor de facturas cualificadas", antes de la entrada en vigor del Sistema de Facturas Cualificadas el 1 de octubre de 2023. Las empresas registradas reciben un número de registro de 14 dígitos (un "número T") que debe figurar en cualquier factura cualificada que emitan. Este período de dos años dio tiempo a las empresas para registrarse antes de que entraran en vigor las normas de crédito fiscal del impuesto al consumo vinculadas al registro.', '["Si suministra a clientes empresariales en Japón y todavía no se ha registrado para obtener un número T, verifique su estado de registro ante la NTA antes de que las normas de crédito fiscal descritas en el siguiente hito afecten a sus clientes", "Confirme que su software de facturación cuenta con un campo para el número T de 14 dígitos antes de la fecha de entrada en vigor de 2023"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-registration-opens-2021', 'de', 'Registrierung für das Qualified Invoice System bei der Nationalen Steuerbehörde beginnt', 'Ab dem 1. Oktober 2021 konnten Unternehmen bei Japans Nationaler Steuerbehörde (NTA) die Registrierung als „qualifizierter Rechnungsaussteller" beantragen, im Vorgriff auf das Inkrafttreten des Qualified Invoice System am 1. Oktober 2023. Registrierte Unternehmen erhalten eine 14-stellige Registrierungsnummer (eine „T-Nummer"), die auf jeder von ihnen ausgestellten qualifizierten Rechnung erscheinen muss. Diese zweijährige Vorlaufzeit gab Unternehmen Zeit zur Registrierung, bevor die an die Registrierung geknüpften Vorsteuerabzugsregeln in Kraft traten.', '["Wenn Sie Geschäftskunden in Japan beliefern und sich noch nicht für eine T-Nummer registriert haben, prüfen Sie Ihren Registrierungsstatus bei der NTA, bevor die im nächsten Meilenstein beschriebenen Vorsteuerabzugsregeln Ihre Kunden betreffen", "Stellen Sie sicher, dass Ihre Rechnungssoftware vor dem Inkrafttreten 2023 über ein Feld für die 14-stellige T-Nummer verfügt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-registration-opens-2021', 'fr', 'Ouverture des inscriptions au régime des factures qualifiées auprès de l''administration fiscale nationale', 'À compter du 1er octobre 2021, les entreprises ont pu commencer à demander auprès de l''administration fiscale nationale du Japon (NTA) leur enregistrement en tant qu''« émetteur de factures qualifiées », en amont de l''entrée en vigueur du régime des factures qualifiées le 1er octobre 2023. Les entreprises enregistrées reçoivent un numéro d''enregistrement à 14 chiffres (un « numéro T ») qui doit figurer sur toute facture qualifiée qu''elles émettent. Ce délai de deux ans a laissé aux entreprises le temps de s''enregistrer avant l''entrée en vigueur des règles de crédit de taxe sur la consommation liées à l''enregistrement.', '["Si vous fournissez des clients professionnels au Japon et que vous ne vous êtes pas encore enregistré pour obtenir un numéro T, vérifiez votre statut d''enregistrement auprès de la NTA avant que les règles de crédit de taxe décrites dans le jalon suivant n''affectent vos clients", "Vérifiez que votre logiciel de facturation dispose d''un champ pour le numéro T à 14 chiffres avant la date d''entrée en vigueur de 2023"]');

-- jp-invoice-system-effective-2023
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-invoice-system-effective-2023', 'es', 'Entra en vigor el Sistema de Facturas Cualificadas (Sistema de Facturas)', 'A partir del 1 de octubre de 2023, entró en vigor el Sistema de Facturas Cualificadas de Japón (適格請求書等保存方式) conforme a la Ley del Impuesto al Consumo. Para poder deducir el crédito fiscal soportado en una compra, un cliente empresarial generalmente necesita una "factura cualificada" -- emitida por un proveedor registrado ante la NTA y que contenga un contenido obligatorio específico: el nombre del emisor y su número T de 14 dígitos, la fecha de emisión, una descripción desglosada de los bienes o servicios, los importes diferenciados según el tipo de impuesto al consumo aplicable y el importe total del impuesto al consumo. Es fundamental señalar que esto NO es un mandato de emisión de facturación electrónica: las facturas cualificadas en papel y en PDF son ambas plenamente válidas, y nada en la ley exige que la factura se transmita o emita electrónicamente. Se trata de un régimen de registro y documentación vinculado a la elegibilidad para el crédito fiscal. Las facturas cualificadas y los registros relacionados deben conservarse durante un mínimo de 7 años.', '["Confirme que está registrado como emisor de facturas cualificadas ante la NTA si sus clientes empresariales dependen de sus facturas para el crédito fiscal soportado", "Verifique que su plantilla o software de facturación incluye los seis elementos obligatorios de la factura cualificada, incluido su número T -- el formato, papel, PDF o electrónico, sigue siendo su elección"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-invoice-system-effective-2023', 'de', 'Das Qualified Invoice System (Rechnungssystem) tritt in Kraft', 'Ab dem 1. Oktober 2023 trat Japans Qualified Invoice System (適格請求書等保存方式) im Rahmen des Umsatzsteuergesetzes in Kraft. Um den Vorsteuerabzug für einen Einkauf geltend zu machen, benötigt ein Geschäftskunde in der Regel eine „qualifizierte Rechnung" -- ausgestellt von einem bei der NTA registrierten Lieferanten und mit bestimmtem Pflichtinhalt: Name des Ausstellers und dessen 14-stellige T-Nummer, Ausstellungsdatum, eine aufgeschlüsselte Beschreibung der Waren/Dienstleistungen, nach dem geltenden Umsatzsteuersatz getrennt ausgewiesene Beträge und der Gesamtbetrag der Umsatzsteuer. Entscheidend: Dies ist KEINE E-Rechnungspflicht -- Papier- und PDF-Rechnungen sind beide vollständig gültig, und nichts im Gesetz verlangt, dass die Rechnung elektronisch übermittelt oder ausgestellt wird. Es handelt sich um ein Registrierungs- und Dokumentationssystem, das an die Vorsteuerabzugsberechtigung geknüpft ist. Qualifizierte Rechnungen und zugehörige Aufzeichnungen müssen mindestens 7 Jahre lang aufbewahrt werden.', '["Prüfen Sie, ob Sie als qualifizierter Rechnungsaussteller bei der NTA registriert sind, wenn sich Ihre Geschäftskunden für den Vorsteuerabzug auf Ihre Rechnungen verlassen", "Stellen Sie sicher, dass Ihre Rechnungsvorlage oder -software alle sechs Pflichtangaben der qualifizierten Rechnung enthält, einschließlich Ihrer T-Nummer -- das Format, Papier, PDF oder elektronisch, bleibt Ihnen überlassen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-invoice-system-effective-2023', 'fr', 'Entrée en vigueur du régime des factures qualifiées (régime de facturation)', 'À compter du 1er octobre 2023, le régime des factures qualifiées du Japon (適格請求書等保存方式) est entré en vigueur en vertu de la loi sur la taxe à la consommation. Pour pouvoir déduire la taxe en amont sur un achat, un client professionnel a généralement besoin d''une « facture qualifiée » -- émise par un fournisseur enregistré auprès de la NTA et comportant un contenu obligatoire précis : le nom de l''émetteur et son numéro T à 14 chiffres, la date d''émission, une description détaillée des biens/services, des montants ventilés selon le taux de taxe à la consommation applicable, et le montant total de la taxe à la consommation. Point essentiel : il ne s''agit PAS d''une obligation de facturation électronique -- les factures qualifiées papier et PDF sont toutes deux pleinement valables, et rien dans la loi n''exige que la facture soit transmise ou émise électroniquement. C''est un régime d''enregistrement et de documentation lié à l''éligibilité au crédit de taxe. Les factures qualifiées et les documents associés doivent être conservés pendant un minimum de 7 ans.', '["Vérifiez que vous êtes enregistré en tant qu''émetteur de factures qualifiées auprès de la NTA si vos clients professionnels s''appuient sur vos factures pour le crédit de taxe en amont", "Vérifiez que votre modèle ou logiciel de facturation inclut les six éléments obligatoires de la facture qualifiée, y compris votre numéro T -- le format, papier, PDF ou électronique, reste à votre discrétion"]');

-- jp-pint-implementation-plan-2024
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-pint-implementation-plan-2024', 'es', 'La Agencia Digital anuncia el plan de implementación de JP PINT / Wildcard Scheme', 'El 30 de septiembre de 2024, la Agencia Digital de Japón anunció un plan de implementación que abarca JP PINT -- la especificación de facturación electrónica de Japón conforme con Peppol PINT BIS Billing, desarrollada junto con el organismo sectorial EIPA -- y una extensión denominada "Wildcard Scheme". Esto continúa desarrollando la capa voluntaria de facturación electrónica que coexiste, y se mantiene totalmente separada, del Sistema de Facturas Cualificadas obligatorio en papel o electrónico que entró en vigor el año anterior. Ninguna empresa está obligada a adoptar JP PINT ni Peppol.', '["Si sus socios comerciales avanzan hacia la facturación electrónica estructurada, evalúe si adoptar JP PINT/Peppol tiene sentido para su empresa -- sigue siendo totalmente opcional", "Siga las futuras actualizaciones de la especificación JP PINT a través de la propia página de JP PINT de la Agencia Digital"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-pint-implementation-plan-2024', 'de', 'Digital Agency kündigt Umsetzungsplan für JP PINT / Wildcard Scheme an', 'Am 30. September 2024 kündigte Japans Digital Agency einen Umsetzungsplan an, der JP PINT -- Japans Peppol-PINT-BIS-Billing-konforme E-Rechnungsspezifikation, entwickelt gemeinsam mit dem Branchenverband EIPA -- sowie eine Erweiterung namens „Wildcard Scheme" umfasst. Damit wird die freiwillige elektronische E-Rechnungsebene weiter ausgebaut, die neben dem im Vorjahr in Kraft getretenen verpflichtenden Papier-oder-elektronisch-Qualified-Invoice-System besteht und davon vollständig getrennt bleibt. Kein Unternehmen ist verpflichtet, JP PINT oder Peppol einzuführen.', '["Wenn sich Ihre Handelspartner in Richtung strukturierter E-Rechnungen bewegen, prüfen Sie, ob die Einführung von JP PINT/Peppol für Ihr Unternehmen sinnvoll ist -- sie bleibt vollständig freiwillig", "Verfolgen Sie künftige JP-PINT-Spezifikationsaktualisierungen über die eigene JP-PINT-Seite der Digital Agency"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-pint-implementation-plan-2024', 'fr', 'L''Agence numérique annonce le plan de mise en œuvre de JP PINT / Wildcard Scheme', 'Le 30 septembre 2024, l''Agence numérique du Japon a annoncé un plan de mise en œuvre couvrant JP PINT -- la spécification de facturation électronique du Japon conforme à Peppol PINT BIS Billing, développée avec l''organisme sectoriel EIPA -- ainsi qu''une extension appelée « Wildcard Scheme ». Cela poursuit le développement de la couche volontaire de facturation électronique qui coexiste avec le régime obligatoire des factures qualifiées, papier ou électronique, entré en vigueur l''année précédente, et en reste entièrement distincte. Aucune entreprise n''est tenue d''adopter JP PINT ou Peppol.', '["Si vos partenaires commerciaux évoluent vers la facturation électronique structurée, évaluez si l''adoption de JP PINT/Peppol est pertinente pour votre entreprise -- cela reste entièrement facultatif", "Suivez les futures mises à jour de la spécification JP PINT via la page JP PINT de l''Agence numérique elle-même"]');

-- jp-transitional-relief-70pct-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-transitional-relief-70pct-2026', 'es', 'El alivio transitorio del crédito fiscal para pequeñas empresas baja al 70%', 'A partir del 1 de octubre de 2026, el alivio transitorio que permite a los compradores deducir parte del impuesto al consumo en las compras a proveedores NO registrados (aquellos que no se han acogido al Sistema de Facturas Cualificadas) baja del 80% al 70%, según el calendario publicado por la Agencia Nacional Tributaria. Esta reducción escalonada -- 80% desde octubre de 2023, 70% desde octubre de 2026, 50% desde octubre de 2028, 30% desde octubre de 2030 -- incrementa gradualmente el coste fiscal de comprar a proveedores no registrados, un incentivo económico para registrarse más que una sanción directa.', '["Si compra a proveedores que no se han registrado en el Sistema de Facturas Cualificadas, presupueste la reducción al 70% de la parte deducible en esas compras a partir de esta fecha", "Considere si animar a sus proveedores no registrados a registrarse reduciría su propia exposición fiscal en el futuro"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-transitional-relief-70pct-2026', 'de', 'Übergangsregelung zum Vorsteuerabzug für Kleinunternehmen sinkt auf 70 %', 'Ab dem 1. Oktober 2026 sinkt die Übergangsregelung, die es Käufern erlaubt, einen Teil der Umsatzsteuer auf Einkäufe von NICHT registrierten Lieferanten (solchen, die sich nicht für das Qualified Invoice System entschieden haben) abzuziehen, gemäß dem veröffentlichten Zeitplan der Nationalen Steuerbehörde von 80 % auf 70 %. Diese stufenweise Reduzierung -- 80 % ab Oktober 2023, 70 % ab Oktober 2026, 50 % ab Oktober 2028, 30 % ab Oktober 2030 -- erhöht schrittweise die steuerlichen Kosten des Einkaufs bei nicht registrierten Lieferanten und ist ein wirtschaftlicher Anreiz zur Registrierung, keine direkte Sanktion.', '["Wenn Sie von Lieferanten einkaufen, die sich nicht für das Qualified Invoice System registriert haben, kalkulieren Sie ab diesem Datum den auf 70 % reduzierten abzugsfähigen Anteil dieser Einkäufe ein", "Prüfen Sie, ob eine Ermutigung Ihrer nicht registrierten Lieferanten zur Registrierung Ihre eigene Steuerbelastung künftig verringern würde"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-transitional-relief-70pct-2026', 'fr', 'L''allègement transitoire du crédit de taxe en amont pour les petites entreprises passe à 70 %', 'À compter du 1er octobre 2026, l''allègement transitoire qui permet aux acheteurs de déduire une partie de la taxe à la consommation sur les achats effectués auprès de fournisseurs NON enregistrés (ceux qui n''ont pas adhéré au régime des factures qualifiées) passe de 80 % à 70 %, selon le calendrier publié par l''administration fiscale nationale. Cette réduction progressive -- 80 % à partir d''octobre 2023, 70 % à partir d''octobre 2026, 50 % à partir d''octobre 2028, 30 % à partir d''octobre 2030 -- augmente progressivement le coût fiscal des achats auprès de fournisseurs non enregistrés, une incitation économique à l''enregistrement plutôt qu''une sanction directe.', '["Si vous achetez auprès de fournisseurs qui ne se sont pas enregistrés au régime des factures qualifiées, prévoyez la réduction à 70 % de la part déductible de ces achats à compter de cette date", "Envisagez si encourager vos fournisseurs non enregistrés à s''enregistrer réduirait votre propre exposition fiscale à l''avenir"]');

-- jp-transitional-relief-50pct-2028
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-transitional-relief-50pct-2028', 'es', 'El alivio transitorio vuelve a bajar al 50%, con nuevas reducciones ya programadas', 'A partir del 1 de octubre de 2028, la misma reducción escalonada del alivio transitorio de la NTA para compras a proveedores no registrados vuelve a bajar, del 70% al 50%. Le siguen nuevas reducciones programadas bajo el mismo marco: 30% desde el 1 de octubre de 2030 hasta el 30 de septiembre de 2031, tras lo cual se espera que el alivio se elimine por completo, aunque la fuente de la NTA consultada no confirmó explícitamente ese desenlace. Por separado, las empresas más pequeñas (con ventas sujetas a impuesto de 100 millones de JPY o menos, o 50 millones de JPY o menos en determinados períodos especificados) pueden seguir reclamando el crédito en compras inferiores a 10.000 JPY con impuesto incluido usando únicamente registros contables, sin necesidad de factura cualificada, hasta el 30 de septiembre de 2029.', '["Incorpore a su planificación a medio plazo la disminución de la parte deducible -- 50% desde octubre de 2028, 30% desde octubre de 2030 -- si una parte significativa de sus compras proviene de proveedores no registrados", "Si es una empresa más pequeña, compruebe si la excepción de solo registro contable para compras inferiores a 10.000 JPY, vigente hasta el 30 de septiembre de 2029, reduce su carga de facturas cualificadas para compras de bajo valor"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-transitional-relief-50pct-2028', 'de', 'Übergangsregelung sinkt erneut auf 50 %, weitere Reduzierungen bereits geplant', 'Ab dem 1. Oktober 2028 sinkt die gleiche stufenweise Übergangsregelung der NTA für Einkäufe von nicht registrierten Lieferanten erneut, von 70 % auf 50 %. Weitere geplante Reduzierungen folgen im selben Rahmen: 30 % vom 1. Oktober 2030 bis zum 30. September 2031, danach wird erwartet, dass die Regelung vollständig entfällt, auch wenn die geprüfte NTA-Quelle diesen Endzustand nicht ausdrücklich bestätigte. Getrennt davon können kleinere Unternehmen (mit steuerpflichtigen Umsätzen von höchstens 100 Millionen JPY, oder höchstens 50 Millionen JPY für bestimmte festgelegte Zeiträume) weiterhin bis zum 30. September 2029 den Vorsteuerabzug für Einkäufe unter 10.000 JPY inklusive Steuer allein anhand von Buchführungsunterlagen geltend machen, ohne dass eine qualifizierte Rechnung erforderlich ist.', '["Berücksichtigen Sie den sinkenden abzugsfähigen Anteil -- 50 % ab Oktober 2028, 30 % ab Oktober 2030 -- in Ihrer mittelfristigen Planung, wenn ein erheblicher Teil Ihrer Einkäufe von nicht registrierten Lieferanten stammt", "Prüfen Sie als kleineres Unternehmen, ob die bis zum 30. September 2029 geltende Ausnahme für reine Buchführungsunterlagen bei Einkäufen unter 10.000 JPY Ihren Aufwand für qualifizierte Rechnungen bei geringwertigen Einkäufen verringert"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jp-transitional-relief-50pct-2028', 'fr', 'L''allègement transitoire redescend à 50 %, avec de nouvelles réductions déjà programmées', 'À compter du 1er octobre 2028, la même réduction progressive de l''allègement transitoire de la NTA pour les achats auprès de fournisseurs non enregistrés baisse à nouveau, passant de 70 % à 50 %. D''autres réductions programmées suivent dans le même cadre : 30 % du 1er octobre 2030 au 30 septembre 2031, après quoi l''allègement devrait être totalement supprimé, bien que la source de la NTA consultée n''ait pas explicitement confirmé cette issue finale. Par ailleurs, les petites entreprises (chiffre d''affaires taxable de 100 millions de JPY ou moins, ou de 50 millions de JPY ou moins pour certaines périodes spécifiées) peuvent continuer à demander le crédit sur les achats de moins de 10 000 JPY TTC en utilisant uniquement des registres comptables, sans facture qualifiée, jusqu''au 30 septembre 2029.', '["Intégrez la baisse progressive de la part déductible -- 50 % à partir d''octobre 2028, 30 % à partir d''octobre 2030 -- dans votre planification à moyen terme si une part importante de vos achats provient de fournisseurs non enregistrés", "Si vous êtes une petite entreprise, vérifiez si l''exception fondée sur les seuls registres comptables pour les achats de moins de 10 000 JPY, valable jusqu''au 30 septembre 2029, réduit votre charge liée aux factures qualifiées pour les achats de faible valeur"]');
